// The same sign-in form as first launch (Kenneth, 2026-11-07): Continue with
// Google, or an email that stays in the app with its emailed code or the
// password. The server's own sign-in page is never shown.
class Component extends DCLogic {
  componentWillUnmount() { clearTimeout(this._timer); }
  renderVals() {
    const st = this.state || {};
    const controlled = typeof this.props.onChange === 'function';
    const status = controlled ? (this.props.status ?? 'signedOut') : (st.status ?? this.props.status ?? 'signedOut');
    const set = (next) => { if (controlled) this.props.onChange(next); else this.setState({ status: next }); };
    const go = (next) => () => {
      clearTimeout(this._timer);
      set(next);
      if (next === 'waiting' || next === 'code') this._timer = setTimeout(() => set('signedIn'), 2500);
    };
    return {
      email: this.props.email ?? 'alex@example.com',
      isOut: status === 'signedOut' || status === 'waiting' || status === 'code',
      isOffer: status === 'signedOut',
      isEnded: status === 'ended',
      isWaiting: status === 'waiting',
      isCode: status === 'code',
      isIn: status === 'signedIn' || status === 'unavailable',
      isSignedIn: status === 'signedIn',
      isUnavailable: status === 'unavailable',
      google: go('waiting'),
      signUp: go('code'),
      cancel: go('signedOut'),
      signOut: go('signedOut'),
      retry: go('signedIn')
    };
  }
}
</script>
</body>
