12	// The page and the host ship in the same build, so this list and the host's
13	// setup_provider_supported() are two views of the same fact. The host still
14	// validates: an unsupported provider comes back as a visible setup error
15	// rather than a request that never answers.
16	export interface ProviderOption {
17	  id: string;
18	  label: string;
19	  // How the provider's keys start, for the placeholder and the locked field.
20	  prefix: string;
21	}
