23	export const PROVIDERS: ProviderOption[] = [
24	  { id: 'anthropic', label: 'Anthropic', prefix: 'sk-ant-' },
25	  { id: 'openai', label: 'OpenAI', prefix: 'sk-' },
26	  { id: 'openrouter', label: 'OpenRouter', prefix: 'sk-or-' },
27	];
