36	// The shared sign-in's controls, as the Agent page's bridge carries them out.
37	// Every window that signs in speaks the same messages.
38	export function accountSignInActions(send: (type: PageMessageType, payload: object) => void): SignInActions {
39	  return {
40	    google: () => send('account_sign_in', {}),
41	    email: (email) => send('account_email', { email }),
42	    sendCode: () => send('account_send_code', {}),
43	    code: (code) => send('account_code', { code }),
44	    password: (password) => send('account_password', { password }),
45	    cancel: () => send('account_cancel', {}),
