157	// What is stored for a provider, as its row's status line says it.
158	// 'sessionOnly' is a key that passed its check but could not be written to
159	// this computer: it works until JusPrin restarts.
160	export type KeyStanding = 'none' | 'saved' | 'rejected' | 'sessionOnly';
161	
162	// The row's key form. 'unreachable' is a check that never got an answer, so
163	// the key stays locked for another try; 'refused' is one the provider
164	// answered no to, so the key stays open to correct.
165	export type KeyForm = 'closed' | 'entering' | 'checking' | 'unreachable' | 'refused';
166	
167	const STANDING_LINE: Record<Exclude<KeyStanding, 'none'>, { icon: string; text: string }> = {
168	  saved: { icon: 'check', text: 'Key saved on this computer' },
169	  sessionOnly: { icon: 'triangle-alert', text: 'This key works now, but JusPrin couldn’t save it.' },
170	  rejected: { icon: 'circle-alert', text: 'The provider rejected this key' },
171	};
172	
173	// A key being checked stays visible so it is clear which one is in question,
174	// but only its known start: the rest is never echoed back.
175	function maskedKey(key: string, prefix: string): string {
176	  return `${key.startsWith(prefix) ? prefix : ''}${'•'.repeat(16)}`;
177	}
178	
179	export interface ProviderKeyRowProps {
180	  provider: ProviderOption;
181	  standing: KeyStanding;
182	  // The host's start-and-last-4 hint of the stored key; never the key.
183	  hint?: string;
184	  form: KeyForm;
185	  error?: string;
186	  value: string;
187	  // Another check is running; nothing else may start until it ends.
188	  busy: boolean;
189	  pasteAvailable: boolean;
190	  inputRef: RefObject<HTMLInputElement>;
191	  onChange: (value: string) => void;
192	  onOpen: () => void;
193	  onRemove: () => void;
194	  onCheck: () => void;
195	  onCancel: () => void;
196	  onPaste: () => void;
197	}
198	
199	export function ProviderKeyRow({
200	  provider, standing, hint, form, error, value, busy, pasteAvailable, inputRef,
201	  onChange, onOpen, onRemove, onCheck, onCancel, onPaste,
202	}: ProviderKeyRowProps) {
203	  const name = provider.label;
204	  const replacing = form !== 'closed' && standing !== 'none';
205	  const locked = form === 'checking' || form === 'unreachable';
206	  const fieldId = `agent-key-${provider.id}`;
207	  const line = standing === 'none' ? null : STANDING_LINE[standing];
208	  const keyDown = (event: KeyboardEvent<HTMLInputElement>) => {
209	    if (event.key === 'Enter' && value.trim()) onCheck();
210	    if (event.key === 'Escape') onCancel();
211	  };
212	
213	  return (
214	    <div className="agent-row" data-testid={`agent-key-${provider.id}`}>
215	      <div className="agent-row-line">
216	        <div className="agent-row-copy">
217	          <span className="agent-row-name">{name}</span>
218	          {line ? (
219	            <span className={`agent-row-status agent-row-status--${standing}`} data-testid={`agent-key-${provider.id}-standing`}>
220	              <span className="agent-row-status-label">
221	                <span className={`jp-icon jp-icon-${line.icon}`} aria-hidden="true" />
222	                <span>{line.text}</span>
223	              </span>
224	              {hint && <code className="agent-key-hint">{hint}</code>}
225	            </span>
226	          ) : (
227	            <span className="agent-row-status">No key</span>
228	          )}
229	        </div>
230	        {form === 'closed' && (standing === 'none' ? (
231	          <button type="button" className="agent-row-action" onClick={onOpen} disabled={busy}
232	            aria-label={`Add ${name} key`}>
233	            <span className="jp-icon jp-icon-plus" aria-hidden="true" />
234	            Add key
235	          </button>
236	        ) : (
237	          <div className="agent-row-actions">
238	            <button type="button" className="agent-row-action" onClick={onOpen} disabled={busy}
239	              aria-label={`Replace ${name} key`}>Replace</button>
240	            <button type="button" className="agent-row-action agent-row-action--danger" onClick={onRemove} disabled={busy}
241	              aria-label={`Remove ${name} key`}>Remove</button>
242	          </div>
243	        ))}
244	      </div>
245	
246	      {form !== 'closed' && (
247	        <div className="agent-key-form">
248	          <label className="agent-key-label" htmlFor={fieldId}>{replacing ? `New ${name} key` : `${name} API key`}</label>
249	          <div className={`agent-key-field${locked ? ' agent-key-field--locked' : error ? ' agent-key-field--error' : ''}`}>
250	            {locked ? (
251	              <input id={fieldId} className="agent-key-input" value={maskedKey(value, provider.prefix)} disabled readOnly />
252	            ) : (
253	              <input
254	                ref={inputRef}
255	                id={fieldId}
256	                type="password"
257	                className="agent-key-input"
258	                placeholder={replacing ? 'Paste the new key' : `Paste your ${name} key (${provider.prefix}…)`}
259	                value={value}
260	                aria-invalid={error ? true : undefined}
261	                onChange={(event) => onChange(event.target.value)}
262	                onKeyDown={keyDown}
263	              />
264	            )}
265	            {!locked && pasteAvailable && (
266	              <button type="button" className="link" onClick={onPaste}>Paste</button>
267	            )}
268	          </div>
269	          {error && <p className="agent-key-error" role="alert" data-testid="setup-error">{error}</p>}
270	          <div className="agent-key-actions">
271	            {form === 'checking' ? (
272	              <span className="agent-key-checking">Checking with {name}…</span>
273	            ) : (
274	              <button type="button" className="primary" onClick={onCheck} disabled={!value.trim()}>Check key</button>
275	            )}
276	            <button type="button" className="link" onClick={onCancel}>Cancel</button>
277	            {replacing && form !== 'checking' && hint && (
278	              <span className="agent-key-keeps">Keeps <code>{hint}</code> until the new key passes</span>
279	            )}
280	          </div>
281	        </div>
282	      )}
283	
284	      {form === 'closed' && standing === 'sessionOnly' && (
285	        <p className="agent-row-note">
286	          You’ll need to add it again after JusPrin restarts.
287	        </p>
288	      )}
289	      {form === 'closed' && standing === 'rejected' && (
290	        <p className="agent-row-note">Replace it with a working key, or remove it.</p>
291	      )}
292	    </div>
293	  );
294	}
295	
296	// A check that never reached the provider says nothing about the key.
297	const UNREACHED = new Set(['network_error', 'timeout', 'service_unavailable', 'service_overloaded', 'setup_failed']);
298	
299	export interface ProviderKeysProps {
300	  // Preferences lists the ways one under another and names each one.
301	  heading?: boolean;
302	  setup: SetupStatusPayload;
303	  // Providers with a stored key, by hint; the key itself never reaches the page.
304	  savedKeys: SavedKeyInfo[];
305	  onCheck: (provider: string, apiKey: string) => void;
306	  onCancel: () => void;
307	  onRemove: (provider: string) => void;
308	}
309	
310	// One row per provider. At most one row has its form open: the host checks
311	// one key at a time, and a key typed into one row means nothing to another.
312	export function ProviderKeys({ heading = false, setup, savedKeys, onCheck, onCancel, onRemove }: ProviderKeysProps) {
313	  const [open, setOpen] = useState<string | null>(null);
314	  const [key, setKey] = useState('');
315	  // The open form's key has been sent, so the host's status now speaks for
316	  // it. Typing again makes it a different key that nothing has said anything
317	  // about yet.
318	  const [sent, setSent] = useState(false);
319	  const [pasteAvailable, setPasteAvailable] = useState(false);
320	  const input = useRef<HTMLInputElement>(null);
321	
322	  // Clipboard reads are not granted in every embedded web view; the paste
323	  // shortcut appears only where it will actually work. Typing and the
324	  // platform's own paste always do.
325	  useEffect(() => {
326	    setPasteAvailable(
327	      typeof navigator !== 'undefined' && !!navigator.clipboard && typeof navigator.clipboard.readText === 'function',
328	    );
329	  }, []);
330	
331	  const close = () => {
332	    setOpen(null);
333	    setKey('');
334	    setSent(false);
335	  };
336	
337	  // A key that passes becomes the provider's key (or works until restart),
338	  // so its form has nothing left to do.
339	  useEffect(() => {
340	    if (setup.phase === 'verified') close();
341	  }, [setup.phase]);
342	
343	  useEffect(() => {
344	    if (open) input.current?.focus();
345	  }, [open]);
346	
347	  const busy = setup.phase === 'checking';
348	
349	  const formFor = (provider: ProviderOption): KeyForm => {
350	    if (open !== provider.id) return 'closed';
351	    if (sent && setup.provider === provider.id) {
352	      if (setup.phase === 'checking') return 'checking';
353	      if (setup.phase === 'error') return UNREACHED.has(setup.error?.code ?? '') ? 'unreachable' : 'refused';
354	    }
355	    return 'entering';
356	  };
357	
358	  const errorFor = (provider: ProviderOption, form: KeyForm): string | undefined => {
359	    if (form === 'unreachable') return `Couldn’t reach ${provider.label} to check this key. Nothing was saved. Try again.`;
360	    if (form !== 'refused') return undefined;
361	    if (setup.error?.code === 'invalid_credentials') return `${provider.label} rejected this key. Nothing was saved.`;
362	    return `${setup.error?.message ?? 'The key could not be checked.'} Nothing was saved.`;
363	  };
364	
365	  const paste = () => {
366	    navigator.clipboard
367	      .readText()
368	      .then((text) => {
369	        setKey(text.trim());
370	        setSent(false);
371	        input.current?.focus();
372	      })
373	      .catch(() => {
374	        // Refused at the OS or view level: leave the field alone and let the
375	        // user paste the way they always could.
376	        input.current?.focus();
377	      });
378	  };
379	
380	  return (
381	    <section className="agent-group" aria-label="Your own API key">
382	      <div className="agent-group-head">
