// Where a credential check has got to. 'verified' means the provider
// answered and the Agent is being connected; 'warning' is set when the key
// worked but could not be written to JusPrin's settings.
export type SetupPhase = 'idle' | 'checking' | 'verified' | 'error';

export interface SetupStatusPayload {
  phase: SetupPhase;
  provider?: string;
  elapsedMs?: number;
  error?: AgentErrorInfo;
  warning?: string;
}

// A provider with a stored key, as the host describes it: never the key, only
// its hint ("sk-ant-…a3F9", its known start and last 4 characters), and
// whether the provider refused that key in this session.
export interface SavedKeyInfo {
  provider: string;
  hint: string;
  rejected: boolean;
  // The signed-in email, for the JusPrin account ('jusprin'), whose
  // credential is a sign-in rather than a key.
  account?: string;
}

